import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return 0.5 * x1**2 + 0.7 * x2**2 + 0.3 * x1 * x2 + 0.1 * (x1 + x2)**3 if (x1 + x2) > 0 else 0 + 0.05 * (x1 - 2*x2)

