import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return 0.5 * x1**2 + 0.7 * x2**2 + 0.1 * (x1 + x2)**3 if (x1 + x2) > 0 else 0 + 0.05 * (x1 - x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return 0.5 * x1**2 + 0.7 * x2**2 + 0.3 * x1 * x2 + 0.1 * (x1 + x2)**3 if (x1 + x2) > 0 else 0 + 0.05 * (x1 - 2*x2) + 0.01 * np.sin(5 * (x1 + x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    dist = np.sqrt(x1**2 + x2**2)
    return float(0.5 * (x1**2 + x2**2) + 0.2 * x1 * x2 + 0.3 * x1 + 0.1 * x2 + 0.1 * x1**3 - 0.05 * x2**3 + 0.5 * np.sin(2 * (x1 + x2)) * np.exp(-0.1 * dist) + 1.0)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return 0.5 * x1**2 + 0.7 * x2**2 + 0.3 * x1 * x2 + 0.1 * (x1 + x2)**3 if (x1 + x2 -1) > 0 else 0 + 0.1 * (x1 + x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x_transformed = np.array([x[0] + 0.5 * x[1]**2, x[1] - 0.2 * x[0]**2])
    result = 0.5 * x_transformed[0]**2 + 0.3 * x_transformed[1]**2 + 0.7 * x_transformed[0] * x_transformed[1] + 1.0
    return 0.01 * np.tanh(result)

